import { apiHelpers } from './client';
import { API_ENDPOINTS } from '@/config/constants';
export const authApi = {
    login: (data) => apiHelpers.post(API_ENDPOINTS.AUTH.LOGIN, data),
    register: (data) => apiHelpers.post(API_ENDPOINTS.AUTH.REGISTER, data),
    logout: () => apiHelpers.post(API_ENDPOINTS.AUTH.LOGOUT),
    me: () => apiHelpers.get(API_ENDPOINTS.AUTH.ME),
    refresh: (refreshToken) => apiHelpers.post(API_ENDPOINTS.AUTH.REFRESH, { refresh_token: refreshToken }),
    forgotPassword: (email) => apiHelpers.post(API_ENDPOINTS.AUTH.FORGOT_PASSWORD, { email }),
    resetPassword: (data) => apiHelpers.post(API_ENDPOINTS.AUTH.RESET_PASSWORD, data),
};
export default authApi;
