import axios from 'axios';
import { message } from 'antd';
// Get API URL from environment or default
const API_BASE_URL = process.env.MIX_API_URL || 'http://localhost:8000';
const apiClient = axios.create({
    baseURL: API_BASE_URL,
    headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'X-Requested-With': 'XMLHttpRequest',
    },
    withCredentials: true,
    timeout: 30000, // 30 seconds
});
// Request interceptor - Add token to headers
apiClient.interceptors.request.use((config) => {
    const token = localStorage.getItem('token');
    if (token && config.headers) {
        config.headers.Authorization = `Bearer ${token}`;
    }
    // Add CSRF token
    const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content');
    if (csrfToken && config.headers) {
        config.headers['X-CSRF-TOKEN'] = csrfToken;
    }
    // Add language header
    const language = localStorage.getItem('language') || 'en';
    if (config.headers) {
        config.headers['Accept-Language'] = language;
    }
    return config;
}, (error) => Promise.reject(error));
// Response interceptor - Handle errors
apiClient.interceptors.response.use((response) => {
    // Handle success messages
    if (response.data?.message) {
        message.success(response.data.message);
    }
    return response;
}, async (error) => {
    const originalRequest = error.config;
    // Handle 401 Unauthorized
    if (error.response?.status === 401 && !originalRequest._retry) {
        originalRequest._retry = true;
        // Try to refresh token
        try {
            const refreshToken = localStorage.getItem('refresh_token');
            if (refreshToken) {
                const response = await axios.post(`${API_BASE_URL}/api/auth/refresh`, {
                    refresh_token: refreshToken,
                });
                const { token } = response.data;
                localStorage.setItem('token', token);
                // Retry original request
                if (originalRequest.headers) {
                    originalRequest.headers.Authorization = `Bearer ${token}`;
                }
                return apiClient(originalRequest);
            }
        }
        catch (refreshError) {
            // Refresh failed, logout
            localStorage.removeItem('token');
            localStorage.removeItem('refresh_token');
            window.location.href = '/login';
            return Promise.reject(refreshError);
        }
    }
    // Handle 403 Forbidden
    if (error.response?.status === 403) {
        message.error('You do not have permission to perform this action');
    }
    // Handle 404 Not Found
    if (error.response?.status === 404) {
        message.error('Resource not found');
    }
    // Handle 422 Validation Error
    if (error.response?.status === 422) {
        const errors = error.response.data?.errors;
        if (errors) {
            Object.values(errors).forEach((errorMessages) => {
                if (Array.isArray(errorMessages)) {
                    errorMessages.forEach((msg) => message.error(msg));
                }
            });
        }
        else if (error.response.data?.message) {
            message.error(error.response.data.message);
        }
    }
    // Handle 429 Rate Limit
    if (error.response?.status === 429) {
        message.warning('Too many requests. Please try again later.');
    }
    // Handle 500 Server Error
    if (error.response?.status === 500) {
        message.error('Internal server error. Please try again later.');
    }
    // Handle network errors
    if (!error.response) {
        message.error('Network error. Please check your connection.');
    }
    return Promise.reject(error);
});
// Helper functions for common API operations
export const apiHelpers = {
    get: (url, params) => apiClient.get(url, { params }).then(res => res.data),
    post: (url, data) => apiClient.post(url, data).then(res => res.data),
    put: (url, data) => apiClient.put(url, data).then(res => res.data),
    patch: (url, data) => apiClient.patch(url, data).then(res => res.data),
    delete: (url) => apiClient.delete(url).then(res => res.data),
    upload: (url, formData, onUploadProgress) => apiClient.post(url, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
        onUploadProgress,
    }).then(res => res.data),
};
export default apiClient;
